# Homebrew formula for the Relay Mac helper. Generated by release/release-mac.sh; don't edit the copy
# in the tap by hand.
class Relay < Formula
  desc "Answer Claude Code prompts from your iPhone"
  homepage "https://relay.relay-cloud.workers.dev"
  version "0.2.0"
  license :cannot_represent

  on_arm do
    url "https://github.com/netchuu/homebrew-relay/releases/download/v0.2.0/relay-0.2.0-darwin-arm64.tar.gz"
    sha256 "473dd021fa0a8d7c26689c7004f227edc8ddcd2c92c064d9a5ce89d2c4ff85c4"
  end
  on_intel do
    url "https://github.com/netchuu/homebrew-relay/releases/download/v0.2.0/relay-0.2.0-darwin-x64.tar.gz"
    sha256 "d16254bfb54f2759ecd7b53762ec1b3b0dc0cefea116dee348e6c3b9a7279442"
  end

  depends_on :macos

  def install
    bin.install "relay", "relay-hook"
  end

  def caveats
    <<~EOS
      To finish, add the Claude Code hooks and start the helper:
        relay install
      then pair your iPhone:
        relay pair

      After `brew upgrade relay`, run `relay install` again so the helper restarts on the new version.
    EOS
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/relay --version")
  end
end
